// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading ensures delayRender is handled internally
const { fontFamily: montserratFamily } = loadMontserrat();



export type CinematicTextOverlayProps = Record<string, any>;

const CinematicTextOverlay: React.FC<CinematicTextOverlayProps> = ({
  backgroundColor = "#010308",
  secondaryBackgroundColor = "#06132b",
  transparentBackground = false,
  durationInSeconds = 10,
  items = [
    { text: "MISTAKE", isAccent: false },
    { text: "SHAME", isAccent: true },
    { text: "PRESSURE", isAccent: false },
    { text: "RUSH", isAccent: false },
    { text: "ANOTHER MISTAKE", isAccent: false },
  ],
  textColor = "#ffffff",
  accentColor = "#ff4726",
  arrowColor = "#64b4ff",
  glowIntensity = 40,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const durationInFrames = Math.round(durationInSeconds * fps);

  // Background resolution to prevent parser issues and handle transparency
  const bgLayer = transparentBackground
    ? "transparent"
    : `radial-gradient(circle at center, ${secondaryBackgroundColor} 0%, ${backgroundColor} 100%)`;

  // Slow, introspective push-in (scale up) spanning the entire animation duration
  const scale = interpolate(frame, [0, durationInFrames], [0.96, 1.03], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Circular layout geometry
  const N = items.length;
  const cx = width / 2;
  const cy = height / 2;
  const rText = height * 0.38; // Outer circle for text
  const rArrow = height * 0.26; // Inner circle for connected arrows

  // Generate deterministic subtle background particles
  const particles = useMemo(() => {
    return new Array(40).fill(0).map((_, i) => ({
      x: (random(`x-${i}`) - 0.5) * width * 1.5,
      y: (random(`y-${i}`) - 0.5) * height * 1.5,
      size: random(`size-${i}`) * 2 + 0.5,
      opacity: random(`op-${i}`) * 0.3 + 0.05,
    }));
  }, [width, height]);

  // Animation Timings
  const startOffset = fps * 0.5;
  const staggerDelay = fps * 1.3; // Time between each step revealing
  const fadeDuration = fps * 1; 

  return (
    <AbsoluteFill style={{ background: bgLayer }}>
      <AbsoluteFill style={{ transform: `scale(${scale})` }}>
        {/* Soft Background Particles */}
        <svg width={width} height={height} style={{ position: "absolute" }}>
          {particles.map((p, i) => (
            <circle
              key={i}
              cx={cx + p.x}
              cy={cy + p.y}
              r={p.size}
              fill="#ffffff"
              opacity={p.opacity}
            />
          ))}
        </svg>

        {/* Arrow Loop Layer (SVG) */}
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", overflow: "visible" }}
        >
          {items.map((_, i) => {
            // Angles for the current item and the next item
            const angle1 = -Math.PI / 2 + i * ((2 * Math.PI) / N);
            const angle2 = -Math.PI / 2 + (i + 1) * ((2 * Math.PI) / N);

            // Leave a gap for visual breathing room between arrows
            const gap = 0.25; 
            const startAngle = angle1 + gap;
            const endAngle = angle2 - gap;

            const startX = cx + rArrow * Math.cos(startAngle);
            const startY = cy + rArrow * Math.sin(startAngle);
            const endX = cx + rArrow * Math.cos(endAngle);
            const endY = cy + rArrow * Math.sin(endAngle);

            // Path for the curved connecting arrow
            const pathD = `M ${startX} ${startY} A ${rArrow} ${rArrow} 0 0 1 ${endX} ${endY}`;
            const arcLength = rArrow * (endAngle - startAngle); 

            // Reveal timings for this specific arrow
            const wordDelay = startOffset + i * staggerDelay;
            const arrowDelay = wordDelay + staggerDelay * 0.4;
            const drawDuration = staggerDelay * 0.5;

            const drawProgress = interpolate(
              frame,
              [arrowDelay, arrowDelay + drawDuration],
              [0, 1],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );
            const strokeDashoffset = arcLength * (1 - drawProgress);

            // Tangent rotation for the arrowhead
            const arrowRot = (endAngle * 180) / Math.PI + 90;

            return (
              <g key={`arrow-${i}`}>
                <path
                  d={pathD}
                  fill="none"
                  stroke={arrowColor}
                  strokeWidth={4}
                  strokeDasharray={arcLength}
                  strokeDashoffset={strokeDashoffset}
                  opacity={0.7}
                  strokeLinecap="round"
                />
                <polygon
                  points="-10,-6 0,0 -10,6"
                  fill={arrowColor}
                  opacity={drawProgress}
                  transform={`translate(${endX}, ${endY}) rotate(${arrowRot})`}
                />
              </g>
            );
          })}
        </svg>

        {/* Text Nodes Layer (HTML) */}
        {items.map((item, i) => {
          const angle = -Math.PI / 2 + i * ((2 * Math.PI) / N);
          const x = cx + rText * Math.cos(angle);
          const y = cy + rText * Math.sin(angle);

          const wordDelay = startOffset + i * staggerDelay;
          const wordOpacity = interpolate(
            frame,
            [wordDelay, wordDelay + fadeDuration],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );
          
          const wordScale = interpolate(
            frame,
            [wordDelay, wordDelay + fadeDuration],
            [0.9, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          return (
            <div
              key={`text-${i}`}
              style={{
                position: "absolute",
                left: x,
                top: y,
                transform: `translate(-50%, -50%) scale(${wordScale})`,
                opacity: wordOpacity,
                fontFamily: montserratFamily,
                fontWeight: 700,
                fontSize: width * 0.025,
                color: item.isAccent ? accentColor : textColor,
                textShadow: `0 0 ${glowIntensity}px ${
                  item.isAccent ? accentColor : "rgba(255, 255, 255, 0.2)"
                }`,
                textAlign: "center",
                letterSpacing: "0.15em",
                whiteSpace: "nowrap",
                transition: "none",
                margin: 0,
                padding: 0,
              }}
            >
              {item.text}
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CinematicTextOverlay;